	const pathPrefix = path.resolve(nconf.get('upload_path'), 'files');
	const searchRegex = /\/assets\/uploads\/files\/([^\s")]+\.?[\w]*)/g;

	const _getFullPath = relativePath => path.resolve(pathPrefix, relativePath);
	const _isWithinPath = (root, candidate) => {
		const relative = path.relative(root, candidate);
		return relative && relative !== '..' && !relative.startsWith(`..${path.sep}`) && !path.isAbsolute(relative);
	};
	const _getValidFullPath = async (relativePath) => {
		if (typeof relativePath !== 'string' || !relativePath || relativePath.includes('\0')) {
			return null;
		}
		const fullPath = _getFullPath(relativePath);
		if (!_isWithinPath(pathPrefix, fullPath)) {
			return null;
		}
		try {
			const [realPrefix, realPath] = await Promise.all([
				fs.promises.realpath(pathPrefix),
				fs.promises.realpath(fullPath),
			]);
			return _isWithinPath(realPrefix, realPath) ? fullPath : null;
		} catch (err) {
			if (['ENOENT', 'ENOTDIR', 'EINVAL', 'ELOOP'].includes(err.code)) {
				return null;
			}
			throw err;
		}
	};
	const _filterValidPaths = async (filePaths) => {
		const validPaths = await Promise.all(filePaths.map(async (filePath) => {
			const fullPath = await _getValidFullPath(filePath);
			return fullPath ? filePath : false;
		}));
		return validPaths.filter(Boolean);
	};

	Posts.uploads.deleteFromDisk = async function (filePaths) {
		if (typeof filePaths === 'string') {
			filePaths = [filePaths];
		} else if (!Array.isArray(filePaths)) {
			throw new TypeError('filePaths must be a string or an array');
		}
		await Promise.all(filePaths.map(async (filePath) => {
			const fullPath = await _getValidFullPath(filePath);
			if (fullPath) {
				await file.delete(fullPath);
			}
		}));
	};

	Posts.uploads.sync = async function (pid) {
		// Scans a post's content and updates sorted set of uploads

